const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const point = ee.Geometry.Point([140.468626, -45.432798]);
    const geometry = point.buffer(100000); // 100km radius

    const startDate1 = '2018-11-01';
    const endDate1 = '2019-02-28';

    const startDate2 = '2019-11-01';
    const endDate2 = '2020-02-29';

    const collectionId = 'NASA/OCEANDATA/MODIS-Aqua/L3SMI';
    const band = 'chlor_a';

    // 2. Data Acquisition
    const col1 = ee.ImageCollection(collectionId)
        .filterDate(startDate1, endDate1)
        .filterBounds(geometry)
        .select(band);

    const col2 = ee.ImageCollection(collectionId)
        .filterDate(startDate2, endDate2)
        .filterBounds(geometry)
        .select(band);

    // 3. Data Availability Check
    const size1 = col1.size().getInfo();
    const size2 = col2.size().getInfo();

    console.log(`Images found for 2018-2019: ${size1}`);
    console.log(`Images found for 2019-2020: ${size2}`);

    if (size1 === 0 || size2 === 0) {
        console.log("Evidence: No images found for one or both periods.");
        console.log("C1");
        return;
    }

    // 4. Processing and Calculation
    const meanImage1 = col1.mean();
    const meanImage2 = col2.mean();

    const statsReducer = ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
    });

    const stats1 = meanImage1.reduceRegion({
        reducer: statsReducer,
        geometry: geometry,
        scale: 3000,
        maxPixels: 1e9
    }).getInfo();

    const stats2 = meanImage2.reduceRegion({
        reducer: statsReducer,
        geometry: geometry,
        scale: 3000,
        maxPixels: 1e9
    }).getInfo();

    const mean1 = stats1[`${band}_mean`];
    const count1 = stats1[`${band}_count`];
    const mean2 = stats2[`${band}_mean`];
    const count2 = stats2[`${band}_count`];

    console.log(`2018-2019 Mean Chlorophyll: ${mean1 ? mean1.toFixed(3) : 'N/A'}, Pixels: ${count1}`);
    console.log(`2019-2020 Mean Chlorophyll: ${mean2 ? mean2.toFixed(3) : 'N/A'}, Pixels: ${count2}`);

    // 5. Validation & Final Answer
    if (count1 === 0 || count2 === 0) {
        console.log("Evidence: No valid pixels found after processing for at least one period.");
        console.log("C2");
        return;
    }

    if (mean1 === null || mean2 === null || mean1 === undefined || mean2 === undefined) {
        console.log("Evidence: Calculation resulted in a null value.");
        console.log("C3");
        return;
    }

    if (mean2 > mean1) {
        console.log("A");
    } else {
        console.log("B");
    }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
    console.error(`Error: ${e.toString()}`);
    console.log("D");
});
